import{_ as a,o as t,c as i,ag as e}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"Stop 强制停止","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/Stop.md","filePath":"3. 指令/5. 设置指令/Stop.md","lastUpdated":1778862643000}'),o={name:"3. 指令/5. 设置指令/Stop.md"};function n(r,s,l,p,h,d){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="stop-强制停止" tabindex="-1">Stop 强制停止 <a class="header-anchor" href="#stop-强制停止" aria-label="Permalink to &quot;Stop 强制停止&quot;">​</a></h1><p>该指令是系统中的<strong>强制停止指令</strong>。执行后，它会立即终止当前控制器中所有正在运行的任务（包括主程序和后台任务），并使机器人各轴迅速减速至停止。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>Stop()</p><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p><code>Stop</code> 指令不同于普通的暂停（Pause）。暂停后通常可以从当前位置恢复运行，而 <code>Stop</code> 通常会导致程序指针重置或需要重新启动整个逻辑流程。</p><ol><li><strong>运动终止</strong>：正在执行的运动指令（如 <code>MovL</code>, <code>MovJ</code>）将立即进入减速停止阶段。</li><li><strong>逻辑终止</strong>：所有正在运行的程序脚本立即退出。</li><li><strong>IO 状态</strong>：通常情况下，IO 输出状态会保持当前值，除非在系统设置中配置了停止时自动复位。</li></ol><hr><h2 id="示例-紧急逻辑触发" tabindex="-1">示例：紧急逻辑触发 <a class="header-anchor" href="#示例-紧急逻辑触发" aria-label="Permalink to &quot;示例：紧急逻辑触发&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (DI10 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">THEN</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Stop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 检测到关键异常，立即关停所有任务</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENDIF</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>执行结果：</strong></p><p>如果 <strong>DI10</strong> 信号变为接通状态，系统将执行 <code>Stop</code> 指令，机器人瞬间停止所有动作，所有正在跑的全部中断。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>致命故障保护</strong>：在检测到严重影响生产安全或设备寿命的条件时（如严重的机械干涉、急停信号以外的逻辑保护），强制关停机器人。</li><li><strong>流程终结</strong>：在复杂的自动化流水线中，当完成整个批次任务且无需保持任何中间状态时，作为程序的最后一行使用。</li><li><strong>调试阶段</strong>：在编写复杂的循环逻辑时，放置 <code>Stop</code> 作为安全哨兵，防止程序进入死循环或不受控的运动。</li></ul><hr><h3 id="⚠️-注意事项" tabindex="-1"><strong>⚠️ 注意事项</strong> <a class="header-anchor" href="#⚠️-注意事项" aria-label="Permalink to &quot;**⚠️ 注意事项**&quot;">​</a></h3><ul><li><strong>非紧急停止</strong>：虽然 <code>Stop</code> 会停止机器人，但它属于<strong>软件控制停止</strong>。在涉及人身安全的紧急情况下，应优先使用硬件<strong>急停（E-Stop）</strong>。</li><li><strong>无法直接继续</strong>：执行 <code>Stop</code> 后，通常不能像按下&quot;暂停&quot;键那样简单地&quot;继续&quot;运行，往往需要重新从程序首行或指定的初始化标签开始执行。</li></ul>`,19)])])}const k=a(o,[["render",n]]);export{g as __pageData,k as default};
